SELECT option_name, option_value FROM wp_options WHERE option_name IN ('home','siteurl');
SELECT post_type, post_status, COUNT(*) AS rows_count FROM wp_posts GROUP BY post_type, post_status;
SELECT autoload, COUNT(*) AS rows_count, SUM(OCTET_LENGTH(option_value)) AS value_bytes FROM wp_options GROUP BY autoload;
SELECT meta_key, COUNT(*) AS rows_count, COUNT(DISTINCT post_id) AS posts FROM wp_postmeta WHERE meta_key IN ('_recipe_time','_recipe_views','_recipe_region') GROUP BY meta_key;
SHOW INDEX FROM wp_postmeta;
SHOW INDEX FROM wp_posts;
